function accountUI(){const m=state.member;$('authForm').hidden=!!state.tokens&&!!m;$('logout').hidden=!state.tokens;$('joinForm').hidden=!state.tokens||!!m;$('adminNav').hidden=m?.role!=='admin';$('sessionInfo').replaceChildren(el('p',m?m.status==='approved'?'\u0623\u0647\u0644\u0627\u064B '+m.name+'\u060C \u0639\u0636\u0648\u064A\u062A\u0643 \u0645\u0641\u0639\u0651\u0644\u0629.':m.status==='pending'?'\u0637\u0644\u0628 \u0627\u0644\u0639\u0636\u0648\u064A\u0629 \u0642\u064A\u062F \u0627\u0644\u0645\u0631\u0627\u062C\u0639\u0629.':'\u0627\u0644\u0639\u0636\u0648\u064A\u0629 \u0645\u0648\u0642\u0648\u0641\u0629\u061B \u0631\u0627\u062C\u0639 \u0625\u062F\u0627\u0631\u0629 \u0628\u0631\u0627\u064A\u0645.':state.tokens?'\u0623\u0643\u062F \u0627\u0644\u0628\u0631\u064A\u062F \u0627\u0644\u0625\u0644\u0643\u062A\u0631\u0648\u0646\u064A \u062B\u0645 \u0623\u0643\u0645\u0644 \u0637\u0644\u0628 \u0627\u0644\u0639\u0636\u0648\u064A\u0629.':'\u0633\u062C\u0651\u0644 \u0627\u0644\u062F\u062E\u0648\u0644 \u0623\u0648 \u0623\u0646\u0634\u0626 \u062D\u0633\u0627\u0628\u0627\u064B \u062C\u062F\u064A\u062F\u0627\u064B.','muted'));}
